    private void jButton4ActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_jButton4ActionPerformed
        // TODO add your handling code here:
        String show="";
        System.out.println("Principal diagonal elements are :");
        if(jRadioButton1.isSelected())
        {
            show=jRadioButton1.getText();
            String temp="";
            if(mat.length == mat[0].length)
            {
                for(i=0;i<mat.length;i++)
                {
                    for(j=0;j<mat[0].length;j++)
                    {
                        if(i==j)
                        {
                            temp=temp+"  "+Integer.toString(mat[i][j]);
                            System.out.println("mat[" + i +"]" + j +"]="+mat[i][j]);
                        }
                    }
                 }
                jTextArea2.setText(temp);
            }
            else
                JOptionPane.showMessageDialog(null,"Given order is not symmetric."); 
            }
        else
        {
            show=jRadioButton2.getText();
            String temp="";
            System.out.println("Secondary diagonal elements are :");
            if(mat.length == mat[0].length)
            {
                for(i=0;i<mat.length;i++)
                {
                    for(j=0;j<mat[0].length;j++)
                    {
                        if(i+j==mat.length-1)
                        {
                            temp=temp+"  "+Integer.toString(mat[i][j]);
                            System.out.println("mat[" + i +"]" + j +"]="+mat[i][j]);
                        }
                    }
                 }
                jTextArea3.setText(temp);
            }
            else
                JOptionPane.showMessageDialog(null,"Given order is not symmetric."); 
        }
    }//GEN-LAST:event_jButton4ActionPerformed

